beforeExample:
package test;

import org.eclipse.jdt.core.dom.CompilationUnit;
import org.eclipse.jdt.core.dom.rewrite.ImportRewrite;
import org.eclipse.jdt.ui.CodeStyleConfiguration;

public class TestClass {
    public ImportRewrite getImportRewrite(CompilationUnit unit) {
        // Old API usage
        return CodeStyleConfiguration.createImportRewrite(unit, true);
    }

    public void anotherMethod() {
        // Ensure other CodeStyleConfiguration methods are not affected
        boolean value = CodeStyleConfiguration.hasProjectSpecificSettings(null);
    }
}

afterExample:
package test;

import org.eclipse.jdt.core.dom.CompilationUnit;
import org.eclipse.jdt.core.dom.rewrite.ImportRewrite;
import org.eclipse.jdt.internal.corext.codemanipulation.StubUtility;

public class TestClass {
    public ImportRewrite getImportRewrite(CompilationUnit unit) {
        // New API usage
        return StubUtility.createImportRewrite(unit, true);
    }

    public void anotherMethod() {
        // Ensure other CodeStyleConfiguration methods are not affected
        boolean value = org.eclipse.jdt.ui.CodeStyleConfiguration.hasProjectSpecificSettings(null);
    }
}

negativeExample:
package test;

import org.eclipse.jdt.core.dom.CompilationUnit;
import org.eclipse.jdt.core.dom.rewrite.ImportRewrite;
import org.eclipse.jdt.internal.corext.codemanipulation.StubUtility;

public class AnotherTestClass {
    public ImportRewrite getImportRewrite(CompilationUnit unit) {
        // This already uses the StubUtility, should not be changed
        return StubUtility.createImportRewrite(unit, true);
    }

    public ImportRewrite createOtherRewrite(CompilationUnit unit) {
        // This uses a different method, should not be changed
        return ImportRewrite.create(unit, true);
    }
}
